import React from "react";
import { BrowserRouter, Routes, Route, NavLink, Link } from "react-router-dom";
import MapView from "./components/MapView";
import ListView from "./components/ListView";
import events from "./data/events";
import "./index.css";

const NAV_ITEMS = [
	{ label: "CARTE", path: "/" },
	{ label: "ÉVÉNEMENTS", path: "/evenements" },
	{ label: "À PROPOS", path: "/a-propos" },
];

function About() {
	return (
		<div style={{ maxWidth: 640, margin: "64px auto", padding: "0 24px" }}>
			<h1 style={{ fontSize: 56, marginBottom: 24, lineHeight: 1 }}>
				Mujawara
			</h1>
			<p
				style={{
					fontSize: 15,
					lineHeight: 1.8,
					color: "var(--text-secondary)",
					fontWeight: 300,
				}}
			>
				Rejoignez-nous pour un mois d'actions internationalistes tout au
				long du mois de juin ! Il s'agit d'un appel mondial lancé à tous
				les espaces et collectifs locaux pour organiser des
				rassemblements, des actions, des repas, des célébrations, des
				collectes de fonds, des marches et des rituels en l'honneur de
				ceux qui sont tombés. L'objectif est de tisser de nouveaux liens
				internationalistes et de mettre en commun nos ressources afin de
				soutenir deux espaces animés par des révolutionnaires syriens et
				soudanais.
			</p>
			{/* ... reste du contenu About inchangé */}
		</div>
	);
}

function Layout() {
	return (
		<div
			style={{
				minHeight: "100vh",
				display: "flex",
				flexDirection: "column",
			}}
		>
			<header
				style={{
					height: 60,
					background: "var(--surface)",
					borderBottom: "1px solid var(--border)",
					display: "flex",
					alignItems: "center",
					padding: "0 32px",
					position: "sticky",
					top: 0,
					zIndex: 1000,
				}}
			>
				<Link
					to="/"
					style={{
						textDecoration: "none",
						fontFamily: "var(--font-title)",
						fontWeight: 800,
						fontStyle: "italic",
						fontSize: 30,
						color: "var(--text-primary)",
						letterSpacing: "-0.5px",
						lineHeight: 1,
					}}
				>
					MUJAWARA
				</Link>

				<nav
					style={{
						position: "absolute",
						left: "50%",
						transform: "translateX(-50%)",
						display: "flex",
						gap: 4,
					}}
				>
					{NAV_ITEMS.map(({ label, path }) => (
						<NavLink
							key={path}
							to={path}
							end={path === "/"}
							style={({ isActive }) => ({
								textDecoration: "none",
								border: "none",
								borderBottom: isActive
									? "2px solid var(--text-primary)"
									: "2px solid transparent",
								borderRadius: 0,
								cursor: "pointer",
								fontFamily: "var(--font-title)",
								fontStyle: "italic",
								fontWeight: 600,
								fontSize: 18,
								color: isActive
									? "var(--text-primary)"
									: "var(--text-muted)",
								padding: "6px 14px",
								transition: "all 0.15s",
								letterSpacing: "-0.3px",
							})}
						>
							{label}
						</NavLink>
					))}
				</nav>
			</header>

			<main style={{ flex: 1 }}>
				<Routes>
					<Route path="/" element={<MapView events={events} />} />
					<Route
						path="/evenements"
						element={<ListView events={events} />}
					/>
					<Route path="/a-propos" element={<About />} />
				</Routes>
			</main>
		</div>
	);
}

export default function App() {
	return (
		<BrowserRouter>
			<Layout />
		</BrowserRouter>
	);
}
